package com.intermarche.e2e.engine.fieldops;
import io.quarkus.test.junit.QuarkusTest;import io.quarkus.narayana.jta.QuarkusTransaction;import io.restassured.response.Response;import org.junit.jupiter.api.Test;import jakarta.inject.Inject;
import com.intermarche.backoffice.domain.stock.*;import com.intermarche.backoffice.domain.util.DateTimeProvider;import com.intermarche.backoffice.engine.stock.TemporalStockService;
import java.util.*;import java.math.BigDecimal;import static io.restassured.RestAssured.given;import static org.junit.jupiter.api.Assertions.*;
@QuarkusTest @jakarta.enterprise.inject.Typed(ReceiptDiscrepancyWorkflowTest.class)
class ReceiptDiscrepancyWorkflowTest extends MissionCoordinationTest {
 @Inject TemporalStockService stocks;
 Response api(String actor,String method,String path,Object body){var r=given().auth().oauth2(actor).contentType("application/json");if(body!=null)r.body(body);var result=r.request(method,path);if(result.statusCode()>=400)System.out.println(path+" "+result.asString());return result;}
 long truck(){return api(f.manager(),"POST","/replenishments",Map.of("storeId",f.store(),"requestKey",key(),"operation","TRUCK_UNLOADING","truckReference","CAM-TEST","start",DateTimeProvider.now().toString(),"end",DateTimeProvider.now().plusHours(1).toString(),"lines",List.of(Map.of("productId",f.product(),"quantity",2,"destinationLocationId",f.location())))).then().statusCode(200).extract().jsonPath().getLong("id");}
 Map<String,Object> report(long order){var line=api(f.manager(),"GET","/replenishments/"+order+"?storeId="+f.store(),null).then().statusCode(200).extract().jsonPath().getLong("lines[0].id");return Map.of("storeId",f.store(),"orderId",order,"productId",f.product(),"expectedSupplyId",line,"kind","SURPLUS","quantity",1,"documentReference","BL-42","comment","Une pièce supplémentaire présente dans le camion","requestKey",key());}
 @Test void surplusIsReceivedOnlyAfterExplicitDecisionAndReplayDoesNotChangeExpectedDelivery(){long order=truck();var report=report(order);var d=api(f.manager(),"POST","/receipt-discrepancies",report).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");api(f.manager(),"POST","/receipt-discrepancies",report).then().statusCode(200);QuarkusTransaction.requiringNew().run(()->{var a=stocks.account(f.store(),f.product());assertEquals(0,stocks.availability(a.id,null,DateTimeProvider.now()).physical.signum());});var decision=Map.of("storeId",f.store(),"id",d.get("id"),"expectedRevision",d.get("revision"),"decision","ACCEPT","reason","Excédent vérifié et accepté sur le bon BL-42","requestKey",key(),"receipt",Map.of("locationId",f.location()));api(f.picker(),"POST","/receipt-discrepancies/decisions",decision).then().statusCode(403);api(f.manager(),"POST","/receipt-discrepancies/decisions",decision).then().statusCode(200);api(f.manager(),"POST","/receipt-discrepancies/decisions",decision).then().statusCode(200);QuarkusTransaction.requiringNew().run(()->{var a=stocks.account(f.store(),f.product());assertEquals(0,BigDecimal.ONE.compareTo(stocks.availability(a.id,null,DateTimeProvider.now()).physical));var o=com.intermarche.backoffice.domain.wms.handling.ReplenishmentOrder.<com.intermarche.backoffice.domain.wms.handling.ReplenishmentOrder>findById(order);assertEquals(2,o.supplies.size());assertEquals(0,BigDecimal.valueOf(2).compareTo(o.supplies.stream().filter(s->!s.reference.startsWith("DELIVERY-GAP")).findFirst().orElseThrow().quantity));assertEquals(1,ReceiptDiscrepancy.count("handlingOrder.id",order));});}
 @Test void receiptPolicyCannotBeBypassedByAcceptingAnExcess(){long order=truck();var d=api(f.manager(),"POST","/receipt-discrepancies",report(order)).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");call(f.manager(),"PUT","/traceability-policies",Map.of("storeId",f.store(),"productId",f.product(),"context","RECEIPT","lotRequired",true,"dateRequired",true)).then().statusCode(200);api(f.manager(),"POST","/receipt-discrepancies/decisions",Map.of("storeId",f.store(),"id",d.get("id"),"expectedRevision",d.get("revision"),"decision","ACCEPT","reason","Contrôle","requestKey",key(),"receipt",Map.of("locationId",f.location()))).then().statusCode(409);QuarkusTransaction.requiringNew().run(()->assertEquals("REPORTED",ReceiptDiscrepancy.<ReceiptDiscrepancy>findById(((Number)d.get("id")).longValue()).state));}
 @Test void anUnexpectedProductCanBeRefusedWithoutInventingStockAndPartialReceiptKeepsRemainder(){long order=truck();Long product=QuarkusTransaction.requiringNew().call(()->{var p=new com.intermarche.backoffice.domain.order.Product();p.ean="U"+key().substring(0,8);p.name="Produit non annoncé";p.productType=com.intermarche.backoffice.domain.order.ProductType.UNIT;p.temperatureZone=com.intermarche.backoffice.domain.store.TemperatureZone.AMBIENT;p.persist();return p.id;});var d=api(f.manager(),"POST","/receipt-discrepancies",Map.of("storeId",f.store(),"orderId",order,"productId",product,"kind","UNEXPECTED","quantity",3,"documentReference","BL-UNEXPECTED","comment","Article absent du bon de livraison","requestKey",key())).then().statusCode(200).extract().jsonPath().<String,Object>getMap("$");var refusal=Map.of("storeId",f.store(),"id",d.get("id"),"expectedRevision",d.get("revision"),"decision","REFUSE","reason","Marchandises refusées au transporteur","requestKey",key());api(f.manager(),"POST","/receipt-discrepancies/decisions",refusal).then().statusCode(200);api(f.manager(),"POST","/receipt-discrepancies/decisions",refusal).then().statusCode(200);QuarkusTransaction.requiringNew().run(()->assertEquals(0,StockAccount.count("store.id=?1 and product.id=?2",f.store(),product)));long supply=api(f.manager(),"GET","/replenishments/"+order+"?storeId="+f.store(),null).then().statusCode(200).extract().jsonPath().getLong("lines[0].id");var receipt=Map.of("storeId",f.store(),"eventKey",key(),"lines",List.of(Map.of("supplyId",supply,"quantity",1)));api(f.manager(),"POST","/replenishments/"+order+"/receipts",receipt).then().statusCode(200);api(f.manager(),"POST","/replenishments/"+order+"/receipts",receipt).then().statusCode(200);QuarkusTransaction.requiringNew().run(()->{var expected=ExpectedSupply.<ExpectedSupply>findById(supply);assertEquals(0,BigDecimal.ONE.compareTo(expected.quantity.subtract(expected.received)));assertEquals(ExpectedSupply.SupplyStatus.EXPECTED,expected.status);});}
 @Test void pickerCanReportAnExcessThroughItsDurableCommandAndManagerAcknowledgesThatObservation(){long order=truck();QuarkusTransaction.requiringNew().run(()->{var o=com.intermarche.backoffice.domain.wms.BaseHandlingOrder.<com.intermarche.backoffice.domain.wms.BaseHandlingOrder>findById(order);o.assignee=com.intermarche.backoffice.domain.store.Employee.find("store.id=?1 and role=?2",f.store(),com.intermarche.backoffice.domain.store.Employee.EmployeeRole.PICKER).firstResult();});command(Map.of("storeId",f.store(),"orderId",order,"action","RESERVE","requestKey",key())).then().statusCode(200);var gap=report(order);Map<String,Object> command=Map.of("storeId",f.store(),"orderId",order,"action","REPORT_DELIVERY_DISCREPANCY","deliveryDiscrepancy",gap,"requestKey",key());var d=command(command).then().statusCode(200).extract().jsonPath().<String,Object>getMap("deliveryDiscrepancy");command(command).then().statusCode(200);api(f.manager(),"POST","/receipt-discrepancies/decisions",Map.of("storeId",f.store(),"id",d.get("id"),"expectedRevision",d.get("revision"),"decision","ACCEPT","reason","Constat du préparateur accepté","requestKey",key(),"receipt",Map.of("locationId",f.location()))).then().statusCode(200);QuarkusTransaction.requiringNew().run(()->assertEquals(1,ReceiptDiscrepancy.count("handlingOrder.id",order)));}

}
